const std = @import("std");
const Allocator = std.mem.Allocator;
const ArrayList = std.ArrayList;

const MAX_WORKING_TOKENS: usize = 700_000;
const MAX_EPISODIC_SUMMARIES: usize = 512;
const VECTOR_DIM: usize = 1536;
const MAX_VECTOR_ENTRIES: usize = 100_000;
const SUMMARY_TRIGGER_RATIO: f32 = 0.8;
const SEGMENT_SIZE: usize = 50;
const TOP_K_RETRIEVAL: usize = 8;
const RAG_BUDGET_TOKENS: usize = 40_000;
const EPISODIC_BUDGET_TOKENS: usize = 50_000;

const WEIGHT_RELEVANCE: f32 = 0.50;
const WEIGHT_RECENCY: f32 = 0.30;
const WEIGHT_ENTITY: f32 = 0.20;

fn estimateTokens(text: []const u8) usize {
    return @max(1, text.len / 4);
}

fn estimateEntityDensity(text: []const u8) u32 {
    var count: u32 = 0;
    var in_word = false;
    var starts_upper = false;
    for (text) |c| {
        if (std.ascii.isAlphabetic(c)) {
            if (!in_word) {
                starts_upper = std.ascii.isUpper(c);
                in_word = true;
            }
        } else {
            if (in_word and starts_upper) count += 1;
            in_word = false;
        }
    }
    if (in_word and starts_upper) count += 1;
    return count;
}

fn cosineSimilarity(a: *const [VECTOR_DIM]f32, b: *const [VECTOR_DIM]f32) f32 {
    var dot: f32 = 0.0;
    var na: f32 = 0.0;
    var nb: f32 = 0.0;
    for (0..VECTOR_DIM) |i| {
        dot += a[i] * b[i];
        na += a[i] * a[i];
        nb += b[i] * b[i];
    }
    const denom = @sqrt(na) * @sqrt(nb);
    if (denom < 1e-10) return 0.0;
    return dot / denom;
}

