pub const AssembledPrompt = struct {
    segments: ArrayList([]const u8),
    total_tokens: usize,
    allocator: Allocator,

    pub fn init(allocator: Allocator) AssembledPrompt {
        return .{
            .segments = ArrayList([]const u8).init(allocator),
            .total_tokens = 0,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *AssembledPrompt) void {
        for (self.segments.items) |seg| self.allocator.free(seg);
        self.segments.deinit();
    }

    pub fn toFullText(self: *AssembledPrompt) ![]u8 {
        var total: usize = 0;
        for (self.segments.items) |s| total += s.len + 1;
        var buf = try self.allocator.alloc(u8, total);
        var pos: usize = 0;
        for (self.segments.items) |s| {
            @memcpy(buf[pos .. pos + s.len], s);
            pos += s.len;
            buf[pos] = '\n';
            pos += 1;
        }
        return buf;
    }
};

pub const ContextManager = struct {
    allocator: Allocator,

    working_messages: ArrayList(Message),
    working_token_count: usize,

    episodic_summaries: ArrayList(EpisodicSummary),
    episodic_token_count: usize,

    vector_entries: ArrayList(VectorEntry),

    next_message_id: u64,
    next_summary_id: u64,
    next_vector_id: u64,
    total_messages_ever: u64,

    pub fn init(allocator: Allocator) ContextManager {
        return .{
            .allocator = allocator,
            .working_messages = ArrayList(Message).init(allocator),
            .working_token_count = 0,
            .episodic_summaries = ArrayList(EpisodicSummary).init(allocator),
            .episodic_token_count = 0,
            .vector_entries = ArrayList(VectorEntry).init(allocator),
            .next_message_id = 1,
            .next_summary_id = 1,
            .next_vector_id = 1,
            .total_messages_ever = 0,
        };
    }

    pub fn deinit(self: *ContextManager) void {
        for (self.working_messages.items) |*m| m.deinit(self.allocator);
        self.working_messages.deinit();
        for (self.episodic_summaries.items) |*s| s.deinit(self.allocator);
        self.episodic_summaries.deinit();
        for (self.vector_entries.items) |*v| v.deinit(self.allocator);
        self.vector_entries.deinit();
    }

    pub fn addMessage(self: *ContextManager, role: Role, content: []const u8, embedding: ?[VECTOR_DIM]f32) !void {
        const content_copy = try self.allocator.dupe(u8, content);
        errdefer self.allocator.free(content_copy);

        const now = std.time.timestamp();
        const tokens = estimateTokens(content);
        const entities = estimateEntityDensity(content);

        const msg = Message{
            .id = self.next_message_id,
            .role = role,
            .content = content_copy,
            .token_count = tokens,
            .timestamp = now,
            .entity_count = entities,
        };

        try self.working_messages.append(msg);
        self.working_token_count += tokens;
        self.next_message_id += 1;
        self.total_messages_ever += 1;

        if (embedding) |emb| {
            try self.storeVector(msg.id, content, emb, now, entities);
        }

        const trigger = @as(usize, @intFromFloat(@as(f32, @floatFromInt(MAX_WORKING_TOKENS)) * SUMMARY_TRIGGER_RATIO));
        if (self.working_token_count > trigger) {
            try self.compressOldestSegment();
        }
    }

    fn storeVector(self: *ContextManager, message_id: u64, content: []const u8, embedding: [VECTOR_DIM]f32, timestamp: i64, entity_count: u32) !void {
        const preview_len = @min(content.len, 512);
        const preview = try self.allocator.dupe(u8, content[0..preview_len]);
        errdefer self.allocator.free(preview);

        if (self.vector_entries.items.len >= MAX_VECTOR_ENTRIES) {
            var oldest = self.vector_entries.orderedRemove(0);
            oldest.deinit(self.allocator);
        }

        try self.vector_entries.append(.{
            .id = self.next_vector_id,
            .message_id = message_id,
            .content_preview = preview,
            .embedding = embedding,
            .timestamp = timestamp,
            .entity_count = entity_count,
        });
        self.next_vector_id += 1;
    }

    fn compressOldestSegment(self: *ContextManager) !void {
        const seg_count = @min(SEGMENT_SIZE, self.working_messages.items.len / 2);
        if (seg_count == 0) return;

        var buf = ArrayList(u8).init(self.allocator);
        defer buf.deinit();

        const seg_start_id = self.working_messages.items[0].id;
        var seg_end_id: u64 = seg_start_id;
        var seg_tokens: usize = 0;

        try buf.appendSlice("[EPISODIC SUMMARY] ");

        for (0..seg_count) |i| {
            const msg = &self.working_messages.items[i];
            seg_end_id = msg.id;
            seg_tokens += msg.token_count;
            const preview_len = @min(msg.content.len, 300);
            try buf.writer().print("{s}: {s} || ", .{ msg.role.str(), msg.content[0..preview_len] });
        }

        _ = seg_tokens;

        const summary_content = try self.allocator.dupe(u8, buf.items);
        errdefer self.allocator.free(summary_content);

        if (self.episodic_summaries.items.len >= MAX_EPISODIC_SUMMARIES) {
            var oldest = self.episodic_summaries.orderedRemove(0);
            self.episodic_token_count -= oldest.token_count;
            oldest.deinit(self.allocator);
        }

        const summary_tokens = estimateTokens(summary_content);
        try self.episodic_summaries.append(.{
            .id = self.next_summary_id,
            .segment_start_id = seg_start_id,
            .segment_end_id = seg_end_id,
            .content = summary_content,
            .token_count = summary_tokens,
            .timestamp = std.time.timestamp(),
            .message_count = @intCast(seg_count),
        });
        self.next_summary_id += 1;
        self.episodic_token_count += summary_tokens;

        for (0..seg_count) |_| {
            var removed = self.working_messages.orderedRemove(0);
            self.working_token_count -= removed.token_count;
            removed.deinit(self.allocator);
        }
    }

    pub fn semanticRetrieve(self: *ContextManager, query_emb: *const [VECTOR_DIM]f32, budget_tokens: usize) !ArrayList(RetrievalResult) {
        var results = ArrayList(RetrievalResult).init(self.allocator);
        errdefer {
            for (results.items) |*r| r.deinit(self.allocator);
            results.deinit();
        }

        if (self.vector_entries.items.len == 0) return results;

        const ScoredIdx = struct { idx: usize, score: f32 };
        var scored = try ArrayList(ScoredIdx).initCapacity(self.allocator, self.vector_entries.items.len);
        defer scored.deinit();

        const now = std.time.timestamp();
        const oldest_ts = self.vector_entries.items[0].timestamp;
        const time_span: f32 = @floatFromInt(@max(1, now - oldest_ts));

        for (self.vector_entries.items, 0..) |*entry, i| {
            const cosine = cosineSimilarity(query_emb, &entry.embedding);
            const age: f32 = @floatFromInt(now - entry.timestamp);
            const recency = 1.0 - @min(1.0, age / time_span);
            const entity_norm = @min(1.0, @as(f32, @floatFromInt(entry.entity_count)) / 20.0);
            const score = WEIGHT_RELEVANCE * cosine + WEIGHT_RECENCY * recency + WEIGHT_ENTITY * entity_norm;
            try scored.append(.{ .idx = i, .score = score });
        }

        const k = @min(TOP_K_RETRIEVAL, scored.items.len);
        for (0..k) |i| {
            var best = i;
            for (i + 1..scored.items.len) |j| {
                if (scored.items[j].score > scored.items[best].score) best = j;
            }
            const tmp = scored.items[i];
            scored.items[i] = scored.items[best];
            scored.items[best] = tmp;
        }

        var used_tokens: usize = 0;
        for (0..k) |i| {
            const entry = &self.vector_entries.items[scored.items[i].idx];
            const tk = estimateTokens(entry.content_preview);
            if (used_tokens + tk > budget_tokens) break;
            const content = try self.allocator.dupe(u8, entry.content_preview);
            errdefer self.allocator.free(content);
            try results.append(.{
                .message_id = entry.message_id,
                .content = content,
                .similarity = scored.items[i].score,
            });
            used_tokens += tk;
        }

        return results;
    }

    pub fn assemblePrompt(
        self: *ContextManager,
        system_prompt: []const u8,
        query_embedding: ?[VECTOR_DIM]f32,
    ) !AssembledPrompt {
        var prompt = AssembledPrompt.init(self.allocator);
        errdefer prompt.deinit();

        {
            const seg = try self.allocator.dupe(u8, system_prompt);
            try prompt.segments.append(seg);
            prompt.total_tokens += estimateTokens(seg);
        }

        if (self.episodic_summaries.items.len > 0) {
            var ep_buf = ArrayList(u8).init(self.allocator);
            defer ep_buf.deinit();
            try ep_buf.appendSlice("=== CONVERSATION HISTORY (SUMMARIZED) ===\n");

            var ep_used: usize = 0;
            var i = self.episodic_summaries.items.len;
            while (i > 0) {
                i -= 1;
                const sum = &self.episodic_summaries.items[i];
                if (ep_used + sum.token_count > EPISODIC_BUDGET_TOKENS) break;
                try ep_buf.writer().print("{s}\n", .{sum.content});
                ep_used += sum.token_count;
            }

            try ep_buf.appendSlice("=== END HISTORY ===\n");
            const seg = try self.allocator.dupe(u8, ep_buf.items);
            try prompt.segments.append(seg);
            prompt.total_tokens += estimateTokens(seg);
        }

        if (query_embedding) |qemb| {
            var retrieved = try self.semanticRetrieve(&qemb, RAG_BUDGET_TOKENS);
            defer {
                for (retrieved.items) |*r| r.deinit(self.allocator);
                retrieved.deinit();
            }

            if (retrieved.items.len > 0) {
                var rag_buf = ArrayList(u8).init(self.allocator);
                defer rag_buf.deinit();
                try rag_buf.appendSlice("=== RELEVANT PAST CONTEXT (RETRIEVED) ===\n");
                for (retrieved.items) |*r| {
                    try rag_buf.writer().print("[relevance={d:.3}] {s}\n", .{ r.similarity, r.content });
                }
                try rag_buf.appendSlice("=== END RETRIEVED CONTEXT ===\n");
                const seg = try self.allocator.dupe(u8, rag_buf.items);
                try prompt.segments.append(seg);
                prompt.total_tokens += estimateTokens(seg);
            }
        }

        {
            var wm_buf = ArrayList(u8).init(self.allocator);
            defer wm_buf.deinit();
            try wm_buf.appendSlice("=== CURRENT CONVERSATION ===\n");
            for (self.working_messages.items) |*msg| {
                try wm_buf.writer().print("{s}: {s}\n", .{ msg.role.str(), msg.content });
            }
            const seg = try self.allocator.dupe(u8, wm_buf.items);
            try prompt.segments.append(seg);
            prompt.total_tokens += estimateTokens(seg);
        }

        return prompt;
    }

    pub fn stats(self: *ContextManager) void {
        std.debug.print(
            "ContextManager | working: {} msgs / {} tokens | episodic: {} summaries / {} tokens | vectors: {} entries | total ever: {}\n",
            .{
                self.working_messages.items.len,
                self.working_token_count,
                self.episodic_summaries.items.len,
                self.episodic_token_count,
                self.vector_entries.items.len,
                self.total_messages_ever,
            },
        );
    }
};

