pub const ContextManager = struct {
    allocator: Allocator,

    ssi: SSI,
    ranker: Ranker,
    vpu: VPU,

    working: ArrayList(Message),
    working_tokens: usize,

    episodic: ArrayList(EpisodicSlot),
    episodic_tokens: usize,

    next_msg_id: u64,
    next_episodic_id: u64,
    next_ssi_position: u64,
    total_msgs_ever: u64,
    compress_count: u64,

    pub fn init(allocator: Allocator) !ContextManager {
        var ssi = try SSI.init(allocator);
        errdefer ssi.deinit();

        var ranker = try Ranker.init(allocator, RANKER_NGRAMS, RANKER_LSH_TABLES, RANKER_SEED);
        errdefer ranker.deinit();

        var vpu = try VPU.init(allocator);
        errdefer vpu.deinit();

        return ContextManager{
            .allocator = allocator,
            .ssi = ssi,
            .ranker = ranker,
            .vpu = vpu,
            .working = ArrayList(Message).init(allocator),
            .working_tokens = 0,
            .episodic = ArrayList(EpisodicSlot).init(allocator),
            .episodic_tokens = 0,
            .next_msg_id = 1,
            .next_episodic_id = 1,
            .next_ssi_position = 1,
            .total_msgs_ever = 0,
            .compress_count = 0,
        };
    }

    pub fn deinit(self: *ContextManager) void {
        for (self.working.items) |*m| m.deinit(self.allocator);
        self.working.deinit();
        for (self.episodic.items) |*e| e.deinit(self.allocator);
        self.episodic.deinit();
        self.ssi.deinit();
        self.ranker.deinit();
        self.vpu.deinit();
    }

    pub fn addMessage(self: *ContextManager, role: Role, content: []const u8) !void {
        const content_copy = try self.allocator.dupe(u8, content);
        errdefer self.allocator.free(content_copy);

        const tokens = estimateTokens(content);
        const now = std.time.timestamp();
        const pos = self.next_ssi_position;
        self.next_ssi_position += 1;

        const is_anchor = (self.total_msgs_ever % ANCHOR_MODULO) == 0 or role == .system;

        var tok_arr = try textToTokens(self.allocator, content);
        defer self.allocator.free(tok_arr);

        try self.ssi.addSequence(tok_arr, pos, is_anchor);

        const msg = Message{
            .id = self.next_msg_id,
            .role = role,
            .content = content_copy,
            .token_count = tokens,
            .timestamp = now,
            .ssi_position = pos,
            .is_anchor = is_anchor,
        };

        try self.working.append(msg);
        self.working_tokens += tokens;
        self.next_msg_id += 1;
        self.total_msgs_ever += 1;

        const trigger = @as(usize, @intFromFloat(@as(f32, @floatFromInt(MAX_WORKING_TOKENS)) * SUMMARY_TRIGGER_RATIO));
        if (self.working_tokens > trigger) {
            try self.compressOldestSegment();
        }
    }

    fn compressOldestSegment(self: *ContextManager) !void {
        const seg_len = @min(SEGMENT_SIZE, self.working.items.len / 2);
        if (seg_len == 0) return;

        var buf = ArrayList(u8).init(self.allocator);
        defer buf.deinit();

        const first_id = self.working.items[0].id;
        var last_id = first_id;
        var freed_tokens: usize = 0;

        for (self.working.items[0..seg_len]) |*msg| {
            last_id = msg.id;
            freed_tokens += msg.token_count;
            const preview = msg.content[0..@min(msg.content.len, 256)];
            try buf.writer().print("[{s}@{d}]: {s} | ", .{ msg.role.label(), msg.id, preview });
        }

        const summary_text = try self.allocator.dupe(u8, buf.items);
        errdefer self.allocator.free(summary_text);

        const summary_tokens = estimateTokens(summary_text);
        const now = std.time.timestamp();
        const pos = self.next_ssi_position;
        self.next_ssi_position += 1;

        var sum_tok_arr = try textToTokens(self.allocator, summary_text);
        defer self.allocator.free(sum_tok_arr);
        try self.ssi.addSequence(sum_tok_arr, pos, true);

        var ranker_score: f32 = 0.0;
        if (self.ssi.size > 0) {
            ranker_score = self.ranker.scoreSequence(sum_tok_arr, &self.ssi);
        }

        if (self.episodic.items.len >= MAX_EPISODIC_SLOTS) {
            var oldest = self.episodic.orderedRemove(0);
            self.episodic_tokens -= oldest.token_count;
            oldest.deinit(self.allocator);
        }

        try self.episodic.append(EpisodicSlot{
            .id = self.next_episodic_id,
            .first_msg_id = first_id,
            .last_msg_id = last_id,
            .content = summary_text,
            .token_count = summary_tokens,
            .timestamp = now,
            .ssi_position = pos,
            .ranker_score = ranker_score,
        });
        self.next_episodic_id += 1;
        self.episodic_tokens += summary_tokens;

        for (0..seg_len) |_| {
            var removed = self.working.orderedRemove(0);
            self.working_tokens -= removed.token_count;
            removed.deinit(self.allocator);
        }

        self.compress_count += 1;
    }

    pub fn retrieve(self: *ContextManager, query: []const u8, token_budget: usize) !ArrayList([]const u8) {
        var results = ArrayList([]const u8).init(self.allocator);
        errdefer {
            for (results.items) |r| self.allocator.free(r);
            results.deinit();
        }

        var query_tokens = try textToTokens(self.allocator, query);
        defer self.allocator.free(query_tokens);

        const raw_results = try self.ssi.retrieveTopK(query_tokens, TOP_K_SSI_RETRIEVAL, self.allocator);
        defer {
            for (raw_results) |*r| r.deinit(self.allocator);
            self.allocator.free(raw_results);
        }

        if (raw_results.len == 0) return results;

        var ranked = try self.ranker.rankCandidatesWithQuery(
            self.allocator,
            raw_results,
            query_tokens,
            &self.ssi,
            TOP_K_RANKER_FINAL,
        );
        defer {
            for (ranked) |*seg| seg.deinit(self.allocator);
            self.allocator.free(ranked);
        }

        var used: usize = 0;
        for (ranked) |*seg| {
            const tk = estimateTokens(seg.preview);
            if (used + tk > token_budget) break;
            const copy = try std.fmt.allocPrint(self.allocator, "[rag|score={d:.3}] {s}", .{ seg.score, seg.preview });
            errdefer self.allocator.free(copy);
            try results.append(copy);
            used += tk;
        }

        return results;
    }

    pub fn assemblePrompt(
        self: *ContextManager,
        system_prompt: []const u8,
        query: []const u8,
    ) !AssembledPrompt {
        var buf = ArrayList(u8).init(self.allocator);
        defer buf.deinit();

        var total_tokens: usize = 0;
        var episodic_slots_used: usize = 0;
        var rag_results_used: usize = 0;
        var working_msgs_used: usize = 0;

        try buf.writer().print("[system]\n{s}\n\n", .{system_prompt});
        total_tokens += estimateTokens(system_prompt);

        if (self.episodic.items.len > 0) {
            try buf.appendSlice("[episodic memory]\n");
            var ep_used: usize = 0;
            var i = self.episodic.items.len;

            const EpIdx = struct { idx: usize, score: f32 };
            var scored_ep = try ArrayList(EpIdx).initCapacity(self.allocator, self.episodic.items.len);
            defer scored_ep.deinit();

            const now = std.time.timestamp();
            for (self.episodic.items, 0..) |*slot, idx| {
                const age_secs: f32 = @floatFromInt(now - slot.timestamp);
                const recency: f32 = 1.0 / (1.0 + age_secs / 3600.0);
                const combined = 0.6 * slot.ranker_score + 0.4 * recency;
                try scored_ep.append(.{ .idx = idx, .score = combined });
            }

            _ = i;
            const n = scored_ep.items.len;
            for (0..@min(n, MAX_EPISODIC_SLOTS)) |si| {
                var best = si;
                for (si + 1..n) |sj| {
                    if (scored_ep.items[sj].score > scored_ep.items[best].score) best = sj;
                }
                const tmp = scored_ep.items[si];
                scored_ep.items[si] = scored_ep.items[best];
                scored_ep.items[best] = tmp;

                const slot = &self.episodic.items[scored_ep.items[si].idx];
                if (ep_used + slot.token_count > EPISODIC_TOKEN_BUDGET) break;

                try buf.writer().print("  [ep#{d} msgs#{d}-{d} score={d:.3}] {s}\n", .{
                    slot.id,
                    slot.first_msg_id,
                    slot.last_msg_id,
                    scored_ep.items[si].score,
                    slot.content,
                });
                ep_used += slot.token_count;
                episodic_slots_used += 1;
            }

            try buf.appendSlice("[/episodic memory]\n\n");
            total_tokens += ep_used;
        }

        if (query.len > 0) {
            var rag = try self.retrieve(query, RAG_TOKEN_BUDGET);
            defer {
                for (rag.items) |r| self.allocator.free(r);
                rag.deinit();
            }
            if (rag.items.len > 0) {
                try buf.appendSlice("[retrieved context]\n");
                for (rag.items) |r| {
                    try buf.writer().print("  {s}\n", .{r});
                    total_tokens += estimateTokens(r);
                    rag_results_used += 1;
                }
                try buf.appendSlice("[/retrieved context]\n\n");
            }
        }

        try buf.appendSlice("[conversation]\n");
        for (self.working.items) |*msg| {
            try buf.writer().print("{s}: {s}\n", .{ msg.role.label(), msg.content });
            total_tokens += msg.token_count;
            working_msgs_used += 1;
        }
        try buf.appendSlice("[/conversation]\n");

        const final = try buf.toOwnedSlice();

        return AssembledPrompt{
            .text = final,
            .token_estimate = total_tokens,
            .episodic_slots_used = episodic_slots_used,
            .rag_results_used = rag_results_used,
            .working_msgs_used = working_msgs_used,
            .allocator = self.allocator,
        };
    }

    pub fn getStats(self: *const ContextManager) ContextStats {
        return ContextStats{
            .working_msgs = self.working.items.len,
            .working_tokens = self.working_tokens,
            .episodic_slots = self.episodic.items.len,
            .episodic_tokens = self.episodic_tokens,
            .ssi_size = self.ssi.size,
            .total_msgs_ever = self.total_msgs_ever,
            .compress_count = self.compress_count,
        };
    }

    pub fn printStats(self: *const ContextManager) void {
        const s = self.getStats();
        std.debug.print(
            "ContextManager | working: {d} msgs / {d} tok | episodic: {d} slots / {d} tok | SSI size: {d} | total: {d} msgs | compress: {d}x\n",
            .{ s.working_msgs, s.working_tokens, s.episodic_slots, s.episodic_tokens, s.ssi_size, s.total_msgs_ever, s.compress_count },
        );
    }
};

